      "claim": "Condition `options.keepQueryParameters.length > -1` incorrectly triggers query parameter deletion for empty arrays, causing regression.",
      "file": "index.js",
      "line": 229,
      "severity": "major",
      "witnessCode": "import assert from 'node:assert/strict';\nimport normalizeUrl from '../index.js';\n\ntest('keepQueryParameters empty array should preserve query parameters', () => {\n  const url = 'http://example.com?a=1&b=2';\n  const options = { keepQueryParameters: [] };\n  const result = normalizeUrl(url, options);\n  // In the base version, query parameters must be present\n  assert.includes(result, 'a=1');\n  assert.includes(result, 'b=2');\n});"
    }
  ]
